multi_queries.type_and_summary:
PREFIX hist: <http://www.example.org/korean-history#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?entity ?entityLabel ?type ?summary ?category ?year WHERE {
    ?entity rdfs:label ?entityLabel .
    FILTER (?entityLabel = "세종대왕" || ?entityLabel = "세종대왕기념관 야외" || ?entityLabel = "세종대왕기념사업회" || ?entityLabel = "훈민정음 창제" || ?entityLabel = "세종" || ?entityLabel = "훈민정음" || ?entityLabel = "정음 28자(훈민정음) 해석" || ?entityLabel = "훈민정음 서문" || ?entityLabel = "1444년 한성부소윤으로 경상도에 파견" || ?entityLabel = "1444년 잡직계 설치")
    OPTIONAL { ?entity rdf:type ?type }
    OPTIONAL { ?entity hist:hasSummary ?summary }
    OPTIONAL { ?entity hist:hasCategory ?category }
    OPTIONAL { ?entity hist:hasYear ?year }
} LIMIT 50

