    FILTER (?entityLabel = "1623년 인조반정" || ?entityLabel = "1623년 인조반정으로 곽산군수 재임" || ?entityLabel = "1623년 인조반정 직후 일시 유배" || ?entityLabel = "1623년 인조반정 후 승문원정자가 됨" || ?entityLabel = "인조반정" || ?entityLabel = "인조반정 후 관료 교체" || ?entityLabel = "인조반정에 참여" || ?entityLabel = "인조반정(1623)" || ?entityLabel = "인조 즉위" || ?entityLabel = "인조 즉위 및 복직")
    OPTIONAL { ?entity rdf:type ?type }
    OPTIONAL { ?entity hist:hasSummary ?summary }
    OPTIONAL { ?entity hist:hasCategory ?category }
    OPTIONAL { ?entity hist:hasYear ?year }
} LIMIT 50

